        public static Aow.Units.AoWE.TRangedAttackAbility P2CreateRangedAttack(int ID, Aow.Rtl.AnsiString Name, sbyte Attack, sbyte Damage, sbyte Repeats, Aow.Units.AoWE.TCombatRange Range, TSet<Aow.Units.AoWE.TDamageType> DamageTypes, int Enchantment)
        {
            Aow.Units.AoWE.TRangedAttackAbility Result = default;
            Aow.Units.AoWE.TRangedAttackAbility Ability = default;
            Ability = Aow.Units.AoWE.TRangedAttackAbility.Create(null);
            Ability.FAbilityID = ID;
            Ability.FAbilityName = Name;
            Ability.FRangeRA = Range;
            Ability.FDamageTypesRA.Value = DamageTypes;
            Ability.FAttackRA = unchecked((sbyte)Attack);
            Ability.FDamageRA = unchecked((sbyte)Damage);
            Ability.FAttackRepeatRA = unchecked((sbyte)Repeats);
            // { Original ignores Enchantment. }
            Result = Ability;
            return Result;
        }

